      // 协议 v1：与宿主侧 src/pages/playground/protocol.ts 手工镜像。本文件零 import 是
      // 「一份原文两条路」的代价；后续 esbuild/OPFS 阶段若协议变复杂，改为打包时共享同一份
      // 协议源码即可（届时跨源路走构建产物，srcdoc 路注入打包后的内联脚本）。

      const PROTOCOL_VERSION = 1
      const CONSOLE_LEVELS = ['log', 'info', 'warn', 'error']

